  gap: var(--spacing-xl);
}

.projects-card {
  background-color: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
}

.projects-card:hover {
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
  transform: translateY(-6px);
}

.projects-card-image {
  width: 100%;
  height: 280px;
  overflow: hidden;
  background-color: var(--color-bg-alt);
}

.projects-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.3s ease;
}

.projects-card:hover .projects-card-image img {
  transform: scale(1.05);
}

.projects-card-content {
  padding: var(--spacing-lg);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.projects-card h3 {
  margin-bottom: var(--spacing-xs);
  font-size: 1.25rem;
}

.projects-card-category {
  display: inline-block;
  padding: var(--spacing-xs) var(--spacing-sm);
  background-color: var(--color-accent-light);
  color: var(--color-primary-dark);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-sm);
  margin-bottom: var(--spacing-sm);
  width: fit-content;
}

.projects-card-text {
  color: var(--color-text-light);
  margin-bottom: auto;
  font-size: 0.95rem;
  line-height: 1.6;
}

.projects-card-link {
  display: inline-block;
  margin-top: var(--spacing-md);
  color: var(--color-primary-dark);
  font-weight: 600;
  text-decoration: none;
  position: relative;
  padding-bottom: 4px;
  border-bottom: 2px solid var(--color-accent);
  transition: all 0.3s ease;
}

.projects-card-link:hover {
  padding-right: 8px;
  color: var(--color-accent);
}

.projects-card-link:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

.projects-cta {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.projects-cta h2 {
  margin-bottom: var(--spacing-md);
}

.projects-cta p {
  font-size: 1.0625rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.projects-cta .btn {
  padding: var(--spacing-md) var(--spacing-xl);
}

@media (max-width: 600px) {
  .projects-hero {
    padding: var(--spacing-xl) 0;
  }

  .projects-hero h1 {
    margin-bottom: var(--spacing-md);
  }

  .projects-hero-text {
    font-size: 1rem;
  }

  .projects-filter {
    padding: var(--spacing-lg) 0;
  }

  .projects-filter-buttons {
    gap: var(--spacing-sm);
  }

  .projects-filter-btn {
    padding: var(--spacing-xs) var(--spacing-md);
    font-size: 0.875rem;
  }

  .projects-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .projects-card-image {
    height: 240px;
  }

  .projects-card-content {
    padding: var(--spacing-md);
  }

  .projects-cta {
    padding: var(--spacing-xl) 0;
  }

  .projects-cta h2 {
    font-size: 1.5rem;
  }

  .projects-cta p {
    font-size: 1rem;
    margin-bottom: var(--spacing-md);
  }
}

@media (min-width: 601px) and (max-width: 1024px) {
  .projects-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1025px) {
  .projects-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.services-hero {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
}

.services-hero h1 {
  margin-bottom: var(--spacing-md);
}

.services-intro {
  font-size: 1.1rem;
  color: var(--color-text-light);
  max-width: 700px;
  line-height: 1.8;
}

.services-card {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  padding: var(--spacing-lg);
  text-align: left;
  height: 100%;
}

.services-card .card-title {
  color: var(--color-primary-dark);
  font-size: 1.25rem;
  margin-bottom: var(--spacing-sm);
}

.services-card .card-text {
  line-height: 1.7;
  color: var(--color-text-light);
}

.services-offerings h2 {
  margin-bottom: var(--spacing-xl);
  text-align: center;
}

.services-process {
  background-color: var(--color-white);
}

.services-process h2 {
  margin-bottom: var(--spacing-md);
}

.services-process > .container > p {
  font-size: 1.05rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-xl);
}

.process-timeline {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-lg);
}

.process-step {
  padding: var(--spacing-lg);
  background-color: var(--color-bg-alt);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--color-accent);
}

.process-number {
  display: inline-block;
  font-family: var(--font-serif);
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-accent);
  margin-bottom: var(--spacing-sm);
}

.process-step h3 {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

.process-step p {
  color: var(--color-text-light);
  line-height: 1.7;
  font-size: 0.95rem;
}

.services-cta {
  background-color: var(--color-primary);
  color: var(--color-white);
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.services-cta h2 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.services-cta p {
  color: var(--color-accent-on-dark);
  font-size: 1.05rem;
  margin-bottom: var(--spacing-lg);
}

.services-cta .btn {
  margin-top: var(--spacing-md);
}

@media (max-width: 600px) {
  .services-hero {
    padding: var(--spacing-xl) 0;
  }

  .services-intro {
    font-size: 1rem;
  }

  .process-timeline {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .process-step {
    padding: var(--spacing-md);
  }

  .process-number {
    font-size: 1.75rem;
  }

  .services-cta {
    padding: var(--spacing-xl) 0;
  }
}

@media (min-width: 601px) {
  .process-timeline {
    grid-template-columns: repeat(2, 1fr);
  }
}

.team-hero {
  background-color: var(--color-primary);
  color: var(--color-white);
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.team-hero h1 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.team-hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-accent-on-dark);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.team-members h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.team-card {
  background-color: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: box-shadow 0.3s ease, transform 0.3s ease;
  display: flex;
  flex-direction: column;
}

.team-card:hover {
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
  transform: translateY(-4px);
}

.team-card-image {
  width: 100%;
  height: 300px;
  object-fit: cover;
  display: block;
}

.team-card-content {
  padding: var(--spacing-lg);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.team-card-name {
  font-size: 1.25rem;
  color: var(--color-primary);
  margin-bottom: var(--spacing-xs);
}

.team-card-role {
  font-weight: 600;
  color: var(--color-accent);
  font-size: 0.95rem;
  margin-bottom: var(--spacing-sm);
}

.team-card-bio {
  color: var(--color-text-light);
  font-size: 0.95rem;
  line-height: 1.7;
  flex-grow: 1;
}

.team-values {
  background-color: var(--color-bg-alt);
}

.team-values h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.values-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-xl);
}

.value-item {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border-radius: var(--radius-md);
  border-left: 4px solid var(--color-accent);
}

.value-item h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-sm);
  font-size: 1.25rem;
}

.value-item p {
  color: var(--color-text-light);
  font-size: 0.95rem;
  line-height: 1.7;
}

.team-cta {
  text-align: center;
  padding: var(--spacing-2xl) 0;
}

@media (max-width: 600px) {
  .team-hero {
    padding: var(--spacing-xl) 0;
  }

  .team-hero-subtitle {
    font-size: 1.1rem;
  }

  .team-card-image {
    height: 250px;
  }

  .team-card-content {
    padding: var(--spacing-md);
  }

  .values-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .team-cta {
    padding: var(--spacing-xl) 0;
  }
}

@media (min-width: 601px) {
  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

.contact-hero {
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.contact-hero h1 {
  color: var(--color-white);
  margin-bottom: var(--spacing-md);
}

.contact-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.contact-form-wrapper {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border-radius: var(--radius-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.contact-form-wrapper h2 {
  margin-bottom: var(--spacing-md);
}

.contact-form .form-group {
  margin-bottom: var(--spacing-md);
}

.contact-form input[type="text"],
.contact-form input[type="email"],
.contact-form input[type="tel"],
.contact-form select,
.contact-form textarea {
  width: 100%;
}

.contact-info-wrapper {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xl);
}

.contact-info-section,
.contact-hours-section {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border-radius: var(--radius-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.contact-info-section h2 {
  margin-bottom: var(--spacing-md);
}

.contact-hours-section h3 {
  margin-bottom: var(--spacing-md);
}

.contact-info-item {
  margin-bottom: var(--spacing-md);
}

.contact-info-item:last-child {
  margin-bottom: 0;
}

.contact-info-item h4 {
  color: var(--color-accent);
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
}

.contact-info-item p {
  margin-bottom: 0;
  color: var(--color-text-light);
  line-height: 1.8;
}

.contact-info-item a {
  color: var(--color-primary-dark);
  font-weight: 600;
}

.contact-info-item a:hover {
  color: var(--color-accent);
}

.contact-hours {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-md);
  border-radius: var(--radius-md);
}

.hours-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-xs) 0;
  border-bottom: 1px solid var(--color-border);
}

.hours-row:last-child {
  border-bottom: none;
}

.hours-row .day {
  font-weight: 600;
  color: var(--color-primary);
}

.hours-row .time {
  color: var(--color-text-light);
}

.contact-map {
  width: 100%;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  margin-top: var(--spacing-lg);
}

@media (max-width: 600px) {
  .contact-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-form-wrapper,
  .contact-info-section,
  .contact-hours-section {
    padding: var(--spacing-md);
  }

  .hours-row {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-xs);
  }

  .contact-map iframe {
    height: 300px !important;
  }
}

@media (min-width: 601px) {
  .contact-content {
    grid-template-columns: 1fr 1fr;
  }
}
